class Solution:
    def buildTree(self, preorder: List[int], inorder: List[int]) -> TreeNode:
        if not preorder:
            return None

        inorder_map = {val: idx for idx, val in enumerate(inorder)}
        root = TreeNode(preorder[0])
        # 栈元素：(子树根节点, 前序区间起点, 前序区间终点, 中序区间起点, 中序区间终点)
        stack = [(root, 0, len(preorder) - 1, 0, len(inorder) - 1)]

        while stack:
            node, pre_start, pre_end, in_start, in_end = stack.pop()
            root_idx = inorder_map[node.val]
            left_size = root_idx - in_start
            right_size = in_end - root_idx

            if left_size > 0:
                node.left = TreeNode(preorder[pre_start + 1])
                stack.append((node.left, pre_start + 1, pre_start + left_size,
                              in_start, root_idx - 1))
            if right_size > 0:
                node.right = TreeNode(preorder[pre_start + left_size + 1])
                stack.append((node.right, pre_start + left_size + 1, pre_end,
                              root_idx + 1, in_end))

        return root
